const rows = $input.all().map(i => i.json);
if (rows.length === 0) return [];

const MODEL = 'gemini-3.6-flash';
const KEY = $env.GEMINI_API_KEY;
const PROMPT = "You are briefing an Australian energy and sustainability consultant.\nThey advise on energy efficiency, building performance, renewables, and the regulatory\nenvironment across Australia, with Victoria as their main market.\n\nFor each article below, return a JSON object with:\n  id               the article id, unchanged\n  summary          two sentences, plain English, what happened and why it matters to them\n  relevance_score  0-100. Score high for Australian regulatory change, funding and grant\n                   programs, energy efficiency and building performance, Victorian schemes\n                   (VEU, Solar Victoria, SEC), and market rule changes. Score low for\n                   overseas consumer news, corporate PR, and anything already routine.\n  topics           up to 4 short lowercase tags\n  entities         named organisations, schemes or people mentioned\n\nReturn ONLY a JSON array, no markdown fence, no commentary.\n\nARTICLES:\n";

const payload = rows.map(r => ({
  id: r.id,
  source: r.source_name,
  category: r.category,
  title: r.title,
  excerpt: (r.summary_raw || '').slice(0, 600),
}));

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${KEY}`,
  json: true,
  timeout: 120000,
  body: {
    contents: [{ parts: [{ text: PROMPT + JSON.stringify(payload, null, 1) }] }],
    generationConfig: { temperature: 0.2, responseMimeType: 'application/json' },
  },
});

const text = res?.candidates?.[0]?.content?.parts?.[0]?.text ?? '[]';
let parsed;
try { parsed = JSON.parse(text); }
catch { throw new Error('Gemini returned unparseable JSON: ' + text.slice(0, 300)); }

const valid = new Set(rows.map(r => r.id));
return parsed
  .filter(p => valid.has(p.id))
  .map(p => ({ json: {
    article_id: p.id,
    summary: String(p.summary ?? '').slice(0, 2000),
    relevance_score: Math.max(0, Math.min(100, Number(p.relevance_score) || 0)),
    topics: Array.isArray(p.topics) ? p.topics.slice(0, 4) : [],
    entities: Array.isArray(p.entities) ? p.entities.slice(0, 10) : [],
    model: MODEL,
  }}));
